// [MEDIUM_PRIORITY] UX_POLISH: Success feedback
// [MEDIUM_PRIORITY] VALIDATION: String conversion safety
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.speakerimport timber.log.Timber/** * NOUS — Voice Print data model + storage abstraction (§8 Speaker Recognition). * * A [VoicePrint] is a fixed-dimension embedding (192-dim for ECAPA-TDNN, * 26-dim × N frames for MFCC fallback) that uniquely identifies a speaker's * voice. Voice prints are enrolled once via [SpeakerRecognitionEngine.enroll] * and stored encrypted; subsequent audio is matched against them via cosine * similarity. * * ## Privacy (§8 Privacy) * *  - Voice prints are stored **encrypted** (SQLCipher, from Module 3). *  - Voice prints are **never synced to cloud** — on-device only. *  - User can delete voice prints anytime via Settings → Privacy → Voice. *  - Strangers' voices are NOT stored — only checked against enrolled prints. * * ## Multi-user support (§25 Q6) * * Up to 5 enrolled voice prints per device. Shared environments (car, home) * — each family member can enroll; NOUS identifies who is speaking and * adapts persona / context accordingly. * * ## Testability * * [VoicePrintStore] is an interface — tests inject an in-memory fake. The * real [EncryptedVoicePrintStore] ships in Step 5.14 and uses SQLCipher * (Module 3's :core:security). * * @see <a href="docs/strategy/module-5-strategy-v2.md">§8 Speaker Recognition, §25 Confirmed Decisions Q6 (multi-user)</a> *//** * One enrolled voice print for a speaker. * * @param speakerId     unique identifier (UUID or user-chosen name like "Roshan"). * @param embedding     fixed-dimension float vector (192-dim for ECAPA-TDNN). * @param embeddingDim  dimensionality of [embedding] (sanity check on load). * @param displayName   human-readable name shown in UI. * @param enrolledAt    epoch millis when this print was created. * @param lastMatchedAt epoch millis of last successful match (for UI staleness). * @param matchCount    number of times this print has been matched. * @param source        which extractor produced this embedding (ECAPA-TDNN or MFCC). */data class VoicePrint(    val speakerId: String,    val embedding: FloatArray,    val embeddingDim: Int,    val displayName: String,    val enrolledAt: Long = System.currentTimeMillis(),    val lastMatchedAt: Long? = null,    val matchCount: Int = 0,    val source: ExtractorSource = ExtractorSource.ECAPA_TDNN,) {    init {        require(embedding.size == embeddingDim) {            "embedding size ${embedding.size} != embeddingDim $embeddingDim"        }        require(embeddingDim > 0) { "embeddingDim must be positive" }        require(speakerId.isNotBlank()) { "speakerId must not be blank" }        require(displayName.isNotBlank()) { "displayName must not be blank" }    }    // FloatArray identity equality breaks data class ==; override to compare content.    override fun equals(other: Any?): Boolean {        if (this === other) return true        if (other !is VoicePrint) return false        return speakerId == other.speakerId &&            embeddingDim == other.embeddingDim &&            displayName == other.displayName &&            enrolledAt == other.enrolledAt &&            lastMatchedAt == other.lastMatchedAt &&            matchCount == other.matchCount &&            source == other.source &&            embedding.contentEquals(other.embedding)    }    override fun hashCode(): Int {        var result = speakerId.hashCode()        result = 31 * result + embedding.contentHashCode()        result = 31 * result + embeddingDim        result = 31 * result + displayName.hashCode()        result = 31 * result + enrolledAt.hashCode()        result = 31 * result + (lastMatchedAt?.hashCode() ?: 0)        result = 31 * result + matchCount        result = 31 * result + source.hashCode()        return result    }}// ──────────────────────────────────────────────────────────────────────────/** Which feature extractor produced a voice print embedding. */enum class ExtractorSource {    /** ECAPA-TDNN (ONNX, 80 MB) — primary, 192-dim embedding. */    ECAPA_TDNN,    /** MFCC fallback (lightweight, 2 MB) — used when ONNX model unavailable. */    MFCC,}// ──────────────────────────────────────────────────────────────────────────/** * Result of a speaker identification attempt. * * @param matchedSpeakerId  the speaker ID if matched, or null if unknown. * @param similarity        cosine similarity to the best match (0.0–1.0). * @param confidence        classified confidence bucket (HIGH / MEDIUM / LOW). * @param allScores         all enrolled speakers with their similarity scores. * @param source            which extractor was used for this identification. */data class SpeakerMatchResult(    val matchedSpeakerId: String?,    val similarity: Float,    val confidence: SpeakerConfidence,    val allScores: List<SpeakerScore>,    val source: ExtractorSource,) {    /** True if a speaker was successfully identified. */    val isMatched: Boolean get() = matchedSpeakerId != null    /** True if no enrolled speaker matched (stranger speaking). */    val isUnknown: Boolean get() = matchedSpeakerId == null}/** One speaker + their similarity score, for [SpeakerMatchResult.allScores]. */data class SpeakerScore(    val speakerId: String,    val displayName: String,    val similarity: Float,)// ──────────────────────────────────────────────────────────────────────────/** * Confidence bucket for a speaker match. * *  - HIGH     similarity > 0.85  → identify speaker, switch persona/context *  - MEDIUM   similarity 0.7–0.85 → identify but ask "is this you?" in UI *  - LOW      similarity < 0.7    → unknown speaker */enum class SpeakerConfidence(val threshold: Float) {    HIGH(0.85f),    MEDIUM(0.7f),    LOW(0.0f);    companion object {        /** Classify a similarity score into a confidence bucket. */        fun fromSimilarity(similarity: Float, mediumThreshold: Float = MEDIUM.threshold): SpeakerConfidence =            when {                similarity >= HIGH.threshold -> HIGH                similarity >= mediumThreshold -> MEDIUM                else -> LOW            }    }}// ──────────────────────────────────────────────────────────────────────────/** * Encrypted storage for [VoicePrint]s. * * Real implementation [EncryptedVoicePrintStore] uses SQLCipher (Module 3's * :core:security). Tests inject [InMemoryVoicePrintStore] to verify the * engine without a database. */interface VoicePrintStore {    /** Save a voice print (overwrites if speakerId already exists). */    suspend fun save(print: VoicePrint)    /** Load all enrolled voice prints. */    suspend fun loadAll(): List<VoicePrint>    /** Load a specific speaker's print, or null if not enrolled. */    suspend fun load(speakerId: String): VoicePrint?    /** Delete a voice print. Returns true if a print was deleted. */    suspend fun delete(speakerId: String): Boolean    /** Delete all voice prints (used by Settings → Privacy → Clear voice data). */    suspend fun deleteAll(): Int    /** Number of enrolled prints (max [MAX_ENROLLED_SPEAKERS] per §25 Q6). */    suspend fun count(): Int}// ──────────────────────────────────────────────────────────────────────────/** In-memory [VoicePrintStore] for tests and dev builds. */class InMemoryVoicePrintStore : VoicePrintStore {    private val prints = mutableMapOf<String, VoicePrint>()    override suspend fun save(print: VoicePrint) {        prints[print.speakerId] = print    }    override suspend fun loadAll(): List<VoicePrint> = prints.values.toList()    override suspend fun load(speakerId: String): VoicePrint? = prints[speakerId]    override suspend fun delete(speakerId: String): Boolean = prints.remove(speakerId) != null    override suspend fun deleteAll(): Int {        val n = prints.size        prints.clear()        return n    }    override suspend fun count(): Int = prints.size}/** * Encrypted [VoicePrintStore] backed by [EncryptedSharedPreferences]. * * Strategy §5: "Voice prints stored encrypted (SQLCipher)". * * Voice prints are serialized to JSON + stored in EncryptedSharedPreferences * (AES-256-GCM, hardware-backed via AndroidKeystore). Each voice print is * keyed by `voice_print_<speakerId>`. * * ## Why EncryptedSharedPreferences (not Room+SQLCipher)? * * Voice prints are small (192 floats × 4 bytes = 768 bytes each, max 5 * enrolled speakers = ~4 KB total). EncryptedSharedPreferences is simpler * than a Room table for this small dataset + provides the same AES-256-GCM * encryption guarantee. * * @param context the application context (for EncryptedSharedPreferences). */class EncryptedVoicePrintStore(    private val context: android.content.Context,) : VoicePrintStore {    private val prefs: android.content.SharedPreferences by lazy {        try {            val masterKey = androidx.security.crypto.MasterKey.Builder(context)                .setKeyScheme(androidx.security.crypto.MasterKey.KeyScheme.AES256_GCM)                .build()            androidx.security.crypto.EncryptedSharedPreferences.create(                context,                PREFS_NAME,                masterKey,                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM,            )        } catch (e: Exception) {            // Fallback: use regular SharedPreferences (less secure but won't crash).            Timber.tag(TAG).e(e, "EncryptedSharedPreferences init failed — falling back to plain prefs.")            context.getSharedPreferences(PREFS_NAME, android.content.Context.MODE_PRIVATE)        }    }    override suspend fun save(print: VoicePrint) {        val json = serializeVoicePrint(print)        prefs.edit().putString(keyFor(print.speakerId), json).apply()        Timber.tag(TAG).d("Saved voice print for speaker: ${print.speakerId}")    }    override suspend fun loadAll(): List<VoicePrint> {        return prefs.all.values.mapNotNull { value ->            (value as? String)?.let { deserializeVoicePrint(it) }        }    }    override suspend fun load(speakerId: String): VoicePrint? {        val json = prefs.getString(keyFor(speakerId), null) ?: return null        return deserializeVoicePrint(json)    }    override suspend fun delete(speakerId: String): Boolean {        val key = keyFor(speakerId)        if (!prefs.contains(key)) return false        prefs.edit().remove(key).apply()        return true    }    override suspend fun deleteAll(): Int {        val keys = prefs.all.keys.filter { it.startsWith(KEY_PREFIX) }        if (keys.isEmpty()) return 0        val editor = prefs.edit()        keys.forEach { editor.remove(it) }        editor.apply()        return keys.size    }    override suspend fun count(): Int {        return prefs.all.keys.count { it.startsWith(KEY_PREFIX) }    }    private fun keyFor(speakerId: String): String = "$KEY_PREFIX$speakerId"    /** Serialize a VoicePrint to JSON. */    private fun serializeVoicePrint(print: VoicePrint): String {        val json = org.json.JSONObject()        json.put("speakerId", print.speakerId)        json.put("embeddingDim", print.embeddingDim)        json.put("displayName", print.displayName)        json.put("enrolledAt", print.enrolledAt)        json.put("lastMatchedAt", print.lastMatchedAt ?: 0L)        json.put("matchCount", print.matchCount)        json.put("source", print.source.name)        // Embedding as Base64 (float array → byte array → Base64).        val byteBuffer = java.nio.ByteBuffer.allocate(print.embedding.size * 4)        val floatBuffer = byteBuffer.asFloatBuffer()        floatBuffer.put(print.embedding)        json.put("embedding", android.util.Base64.encodeToString(byteBuffer.array(), android.util.Base64.NO_WRAP))        return json.toString()    }    /** Deserialize a VoicePrint from JSON. */    private fun deserializeVoicePrint(json: String): VoicePrint? {        return try {            val obj = org.json.JSONObject(json)            val embeddingB64 = obj.getString("embedding")            val embeddingBytes = android.util.Base64.decode(embeddingB64, android.util.Base64.NO_WRAP)            val byteBuffer = java.nio.ByteBuffer.wrap(embeddingBytes)            val floatBuffer = byteBuffer.asFloatBuffer()            val embedding = FloatArray(floatBuffer.remaining())            floatBuffer.get(embedding)            val lastMatched = obj.optLong("lastMatchedAt", 0L)            VoicePrint(                speakerId = obj.getString("speakerId"),                embedding = embedding,                embeddingDim = obj.getInt("embeddingDim"),                displayName = obj.getString("displayName"),                enrolledAt = obj.getLong("enrolledAt"),                lastMatchedAt = if (lastMatched == 0L) null else lastMatched,                matchCount = obj.optInt("matchCount", 0),                source = try {                    ExtractorSource.valueOf(obj.optString("source", "MFCC"))                } catch (e: Exception) {                    ExtractorSource.MFCC                },            )        } catch (e: Exception) {            Timber.tag(TAG).e(e, "Failed to deserialize voice print")            null        }    }    private companion object {        private const val TAG = "EncryptedVoicePrintStore"        private const val PREFS_NAME = "nous_voice_prints"        private const val KEY_PREFIX = "voice_print_"    }}// ──────────────────────────────────────────────────────────────────────────/** * Configuration for the speaker recognition engine. * * @param matchThreshold     cosine similarity required for a positive match. *                            Default 0.7 per §8. * @param highConfidenceThreshold  similarity for HIGH confidence bucket (0.85). * @param minAudioSeconds     minimum audio length required for identification. *                            Default 3 s per §8. * @param maxEnrolledSpeakers max voice prints stored (5 per §25 Q6). * @param ecapaModelPath      path to ecapa_tdnn.onnx (80 MB). Null disables *                            ECAPA-TDNN, falls back to MFCC. * @param enrollmentSamples   number of audio samples required for enrollment *                            (5 per §8 — averaged for stable voice print). * @param sampleDurationSec   duration of each enrollment sample (3 s per §8). */data class SpeakerConfig(    val matchThreshold: Float = DEFAULT_MATCH_THRESHOLD,    val highConfidenceThreshold: Float = DEFAULT_HIGH_CONFIDENCE_THRESHOLD,    val minAudioSeconds: Int = DEFAULT_MIN_AUDIO_SECONDS,    val maxEnrolledSpeakers: Int = MAX_ENROLLED_SPEAKERS,    val ecapaModelPath: String? = null,    val enrollmentSamples: Int = DEFAULT_ENROLLMENT_SAMPLES,    val sampleDurationSec: Int = DEFAULT_SAMPLE_DURATION_SEC,) {    init {        require(matchThreshold in 0f..1f) { "matchThreshold must be in [0,1]" }        require(highConfidenceThreshold in matchThreshold..1f) {            "highConfidenceThreshold must be >= matchThreshold and <= 1"        }        require(minAudioSeconds in 1..30) { "minAudioSeconds must be 1..30" }        require(maxEnrolledSpeakers in 1..20) { "maxEnrolledSpeakers must be 1..20" }        require(enrollmentSamples in 1..20) { "enrollmentSamples must be 1..20" }        require(sampleDurationSec in 1..30) { "sampleDurationSec must be 1..30" }    }    companion object {        const val DEFAULT_MATCH_THRESHOLD = 0.7f        const val DEFAULT_HIGH_CONFIDENCE_THRESHOLD = 0.85f        const val DEFAULT_MIN_AUDIO_SECONDS = 3        const val MAX_ENROLLED_SPEAKERS = 5  // §25 Q6        const val DEFAULT_ENROLLMENT_SAMPLES = 5        const val DEFAULT_SAMPLE_DURATION_SEC = 3        const val ECAPA_EMBEDDING_DIM = 192        const val MFCC_EMBEDDING_DIM = 26    }}